function escapeHTML(text) {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/"/g, '&quot;');
}

const inputData = $input.first()?.json || {};
const execution = inputData.execution || {};
const workflow = inputData.workflow || {};
const error = execution.error || {};

const workflowName = escapeHTML(workflow.name || 'نامشخص');
const failedNode = escapeHTML(execution.lastNodeExecuted || 'نامشخص');
const errorMessage = escapeHTML(error.message || 'خطای غیرمنتظره');
const executionId = execution.id || '';
const executionUrl = execution.url || '';

return [{
  json: {
    workflow_name: workflowName,
    failed_node: failedNode,
    error_message: errorMessage,
    execution_id: executionId,
    execution_url: executionUrl,
    timestamp: new Date().toLocaleString('fa-IR', { timeZone: 'Asia/Tehran' })
  }
}];

